func (s *Scanner) newCmd(ctx context.Context) *exec.Cmd {
	args := s.buildArgs()

	//nolint:gosec // Arguments are passed directly to nmap; users intentionally control args.
	cmd := exec.CommandContext(ctx, s.binaryPath, args...)
